    narration: 'A 256×256×3 noisy image enters at the left. The first residual blocks lift it to 256×256×128 — tall slabs, still full spatial resolution.',
    s: { pass: 'encoder-256', t: 250, mode: 'all' } },
  { title: 'Downsampling',
    narration: 'Each stage halves the spatial size and (twice) doubles the channels: 128×128×128, 64×64×256, 32×32×256, 16×16×512. The boxes get shorter and longer.',
    s: { pass: 'encoder-down', t: 250, mode: 'all' } },
  { title: 'Self-attention stages',
    narration: 'Light blue arrows mark residual blocks with self-attention. They appear only at 16×16 and in the 8×8×512 bottleneck, where global mixing is cheap.',
    s: { pass: 'bottleneck', t: 250, mode: 'attn' } },
  { title: 'Decoder and skip concatenation',
    narration: 'On the way back up, each decoder stage receives the encoder feature map of matching resolution along the salmon Concatenate arrows, restoring the fine detail lost by downsampling.',
    s: { pass: 'decoder', t: 250, mode: 'all' } },
  { title: 'Timestep conditioning',
    narration: 'Sweep t: the embedding of the circled t travels the bottom rail and is injected into every residual block, telling the network how much noise to expect and predict.',
    s: { pass: 'idle', t: 900, mode: 'all' } }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  setPass(st.s.pass);
  state.tTarget = st.s.t; elT.value = st.s.t;
  setMode(st.s.mode);
  elNarr.innerHTML = `<b>${stepIdx + 1}/${STEPS.length} · ${st.title}</b><br>${st.narration}`;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);

/* ── per-frame update ────────────────────────────────────────────────────── */
let lastQ = -1, railPhase = 0, lastTime = performance.now();
function refreshT() {
  const v = Math.round(state.tCur);
  elTv.textContent = v;
  tLbl.div.innerHTML = 't = ' + v;
  const q = Math.round(state.tCur / 20);
  if (q !== lastQ && inputTexHolder) {
    lastQ = q;
    const old = inputTexHolder.tex;
    const tex = noiseTexture('input', Math.pow(state.tCur / 1000, 0.7));
    inputTexHolder.tex = tex;
    inputTexHolder.mat.map = tex;
    inputTexHolder.mat.needsUpdate = true;
    old.dispose();
  }
}
refreshT();

function applyVisuals() {
  const active = state.playing;
  blocks.forEach((b, i) => {
    let dim = false;
    if (state.mode === 'res') dim = ATTN_ADJ.has(i);
    else if (state.mode === 'attn') dim = !ATTN_ADJ.has(i);
    const op = dim ? 0.18 : 1;
    const pulse = active ? Math.max(0, 1 - Math.abs(state.cursor - i) / 1.3) : 0;
    b.mats.forEach(m => {
      m.opacity = op; m.transparent = op < 1;
      m.color.copy(m.userData.base);
      if (pulse > 0) m.color.lerp(HL, 0.72 * pulse);
    });
    b.edgeMat.opacity = op; b.edgeMat.transparent = op < 1;
  });
  gapArrows.forEach(ga => {
    let dim = false;
    if (state.mode === 'res') dim = ga.isAttn;
    else if (state.mode === 'attn') dim = !ga.isAttn;
    const op = dim ? 0.18 : 1;
    ga.mats.forEach(m => { m.opacity = op; m.transparent = op < 1; });
  });
  SKIPS.forEach(sk => {
    const u = (state.cursor - (sk.decIdx - 2.2)) / 2.2;
    const on = state.playing && u >= 0 && u <= 1.04;
    sk.dot.visible = on;
    if (on) sk.dot.position.copy(pathPoint(sk, Math.min(1, u)));
    sk.mats.forEach(m => { m.color.copy(on ? SKIP_H : SKIP_B); });
  });
}

function whereText() {
  if (!state.playing) return 'pass paused · t held';
  const i = Math.round(Math.max(0, Math.min(blocks.length - 1, state.cursor)));
  const sp = blocks[i].spec;
  if (sp.t === 'plane') return sp.side === 'in' ? 'input · 256×256×3' : 'output · predicted noise';
  return `${sp.part} · ${sp.res}×${sp.res}×${sp.ch}`;
}

function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - lastTime) / 1000);
  lastTime = now;

  if (Math.abs(state.tCur - state.tTarget) > 0.4) {
    state.tCur += (state.tTarget - state.tCur) * Math.min(1, dt * 6);
    refreshT();
  } else if (state.tCur !== state.tTarget) { state.tCur = state.tTarget; refreshT(); }

  if (state.playing) {
    state.cursor += dt * 3.0;
    if (state.cursor > state.range[1] + 1.4) state.cursor = state.range[0] - 0.8;
  }
  railPhase = (railPhase + dt * (0.12 + state.tCur / 2600)) % 1;
  railDot.position.set(railStart + (railEnd - railStart) * railPhase, RAIL_Y, RAIL_Z);
  railDot.material.color.setHSL(0.55, 0.45, 0.35 + 0.35 * (1 - state.tCur / 1000));

  applyVisuals();
  elWhere.textContent = whereText();
}
tick();

document.getElementById('btnReset').style.display = '';
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

