<label style="margin-top:6px">Diffusion timestep&nbsp;t: <b id="tVal">250</b>
  <input type="range" id="sldT" min="0" max="1000" step="1" value="250">
</label>
<div style="font-size:10.5px;color:#555;line-height:1.3">
  One scalar t is embedded once and injected into <i>every</i> residual block along the bottom rail.
</div>

<div style="font-weight:bold;margin-top:6px">Block highlighting</div>
<button id="btMode0" class="active">All blocks</button>
<button id="btMode1">Res. block only</button>
<button id="btMode2">Res. block + self-attention</button>

<div style="font-weight:bold;margin-top:6px">Guided tour</div>
<div style="display:flex;gap:4px">
  <button id="btnPrev" style="flex:1">◀ Prev</button>
  <button id="btnNext" style="flex:1">Next ▶</button>
</div>
<div id="narr" style="font-size:11px;line-height:1.4;color:#222;margin-top:2px;min-height:64px"></div>
<div style="font-size:10.5px;color:#666;margin-top:4px">Hover any block to read its tensor shape.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ────────────────────────────────────────────────────────────
// noisy input plane      → BoxGeometry(0.06, 4, 4)  CanvasTexture brown noise
// noisy output plane     → BoxGeometry(0.06, 4, 4)  CanvasTexture grey noise
// feature-map blocks     → BoxGeometry(channelThickness, spatial, spatial)
//                          side faces dark brown #8C4229, +Z front salmon, top light salmon
// block outlines         → LineSegments(EdgesGeometry) black, raycast disabled
// res-block arrows       → Line + ConeGeometry head, #3F5E6E (between blocks)
// self-attn arrows       → Line + ConeGeometry head, #9CC4DA (exactly 3 gaps)
// skip connections       → short steep rise + LONG horizontal rail + steep drop
//                          + cone head, #C86B45, depthTest off
// skip travelling dot    → SphereGeometry(0.085) salmon
// time rail              → Line y=-1.15 + LineLoop circle (radius .3) for 't'
// time injection arrows  → long Line + big cone, #3F5E6E, one per inter-block gap
// legend                 → rounded-rect LineLoop (upper FAR left) + 2 arrows + HTML text
// dimension leaders      → short Line + cone, black, pointing down-left at block corner
// all text               → addLabel HTML (italic serif for dimensions, size ∝ figure scale)
─────────────────────────────────────────────────────────────────────────────*/

const COL = {
  dark: 0x8C4229, front: 0xE0906A, top: 0xEFA37C,
  skip: 0xC86B45, rail: 0x3F5E6E, attn: 0x9CC4DA, ink: 0x111111
};
const HL      = new THREE.Color(0xFFD9A0);
const SKIP_B  = new THREE.Color(COL.skip);
const SKIP_H  = new THREE.Color(0xFF9B58);
const SH      = 0.35355;               // cabinet-oblique screen shift per unit depth

const gFig = new THREE.Group();  scene.add(gFig);

/* ── helpers ─────────────────────────────────────────────────────────────── */
function mkLine(points, color, opts = {}) {
  const l = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(points),
    new THREE.LineBasicMaterial({ color })
  );
  l.raycast = function () {};
  if (opts.onTop) { l.material.depthTest = false; l.renderOrder = opts.order || 10; }
  gFig.add(l);
  return l;
}
function mkArrow(from, to, color, opts = {}) {
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = Math.max(dir.length(), 1e-5); dir.normalize();
  const hl = Math.min(opts.head || 0.14, len * 0.8), hr = opts.headR || 0.052;
  const line = mkLine([from, to.clone().addScaledVector(dir, -hl * 0.75)], color, opts);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(hr, hl, 14),
    new THREE.MeshBasicMaterial({ color }));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  cone.position.copy(to).addScaledVector(dir, -hl / 2);
  if (opts.onTop) { cone.material.depthTest = false; cone.renderOrder = opts.order || 10; }
  cone.raycast = function () {};
  gFig.add(cone);
  return { mats: [line.material, cone.material] };
}
function roundedRect(x, y, w, h, r, z) {
  const pts = [], S = 5;
  const cs = [[x + w - r, y + r, -Math.PI / 2], [x + w - r, y + h - r, 0],
              [x + r, y + h - r, Math.PI / 2], [x + r, y + r, Math.PI]];
  cs.forEach(([cx, cy, a0]) => {
    for (let i = 0; i <= S; i++) {
      const a = a0 + (Math.PI / 2) * (i / S);
      pts.push(new THREE.Vector3(cx + r * Math.cos(a), cy + r * Math.sin(a), z));
    }
  });
  pts.push(pts[0].clone());
  return pts;
}

/* ── noise textures ──────────────────────────────────────────────────────── */
function noiseTexture(kind, tNorm) {
  const N = 120, cv = document.createElement('canvas'); cv.width = cv.height = N;
  const ctx = cv.getContext('2d'), img = ctx.createImageData(N, N), D = img.data;
  const a = kind === 'input' ? Math.max(0.05, tNorm) : 1.0;
  for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) {
    const i = (y * N + x) * 4;
    let r, g, b;
    if (kind === 'input') {
      const u = x / N - 0.5, v = y / N - 0.5, rr = Math.sqrt(u * u + v * v);
      const low = 0.5 + 0.5 * Math.sin(u * 9 + Math.cos(v * 7) * 1.6);
      r = 210 - 38 * low; g = 176 - 44 * low; b = 156 - 44 * low;
      const les = Math.exp(-Math.pow((rr - 0.05) / 0.19, 2) * 2.2);
      r = r * (1 - 0.6 * les) + 34 * les;
      g = g * (1 - 0.68 * les) + 20 * les;
      b = b * (1 - 0.68 * les) + 16 * les;
    } else { r = g = b = 130; }
    D[i]     = r * (1 - a) + Math.random() * 255 * a;
    D[i + 1] = g * (1 - a) + Math.random() * 255 * a;
    D[i + 2] = b * (1 - a) + Math.random() * 255 * a;
    D[i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(cv);
  tex.magFilter = THREE.NearestFilter; tex.minFilter = THREE.LinearFilter;
  return tex;
}

/* ── block sequence ──────────────────────────────────────────────────────── */
const specs = [];
specs.push({ t: 'plane', side: 'in', sp: 4.0, w: 0.06, ch: 3, res: 256, gapAfter: 0.55 });
const encStages = [
  { res: 256, n: 3, sp: 4.0,   w: 0.35, ch: 128 },
  { res: 128, n: 2, sp: 2.0,   w: 0.35, ch: 128 },
  { res: 64,  n: 2, sp: 1.0,   w: 0.70, ch: 256 },
  { res: 32,  n: 2, sp: 0.5,   w: 0.70, ch: 256 },
  { res: 16,  n: 2, sp: 0.25,  w: 1.40, ch: 512 }
];
encStages.forEach(s => { for (let i = 0; i < s.n; i++)
  specs.push({ t: 'box', part: 'encoder', res: s.res, sp: s.sp, w: s.w, ch: s.ch }); });
for (let i = 0; i < 3; i++)
  specs.push({ t: 'box', part: 'bottleneck', res: 8, sp: 0.125, w: 1.4, ch: 512 });
[...encStages].reverse().forEach(s => { for (let i = 0; i < s.n; i++)
  specs.push({ t: 'box', part: 'decoder', res: s.res, sp: s.sp, w: s.w, ch: s.ch }); });
specs[specs.length - 1].gapAfter = 0.55;
specs.push({ t: 'plane', side: 'out', sp: 4.0, w: 0.06, ch: 3, res: 256 });

const GAP = 0.25;
let totalW = 0;
specs.forEach((s, i) => { totalW += s.w + (i < specs.length - 1 ? (s.gapAfter || GAP) : 0); });

const blocks = [];
let runX = -totalW / 2;
let inputTexHolder = null;
specs.forEach((sp, i) => {
  const h = sp.sp, dep = sp.sp, w = sp.w;
  const geo = new THREE.BoxGeometry(w, h, dep);
  let mats, uniq;
  if (sp.t === 'plane') {
    const tex = noiseTexture(sp.side === 'in' ? 'input' : 'out', 0.25);
    const mTex = new THREE.MeshBasicMaterial({ map: tex });
    const mEdg = new THREE.MeshBasicMaterial({ color: 0xBCBCBC });
    mats = [mTex, mTex, mEdg, mEdg, mEdg, mEdg]; uniq = [mTex, mEdg];
    if (sp.side === 'in') inputTexHolder = { mat: mTex, tex };
  } else {
    const mS = new THREE.MeshBasicMaterial({ color: COL.dark });
    const mT = new THREE.MeshBasicMaterial({ color: COL.top });
    const mF = new THREE.MeshBasicMaterial({ color: COL.front });
    mats = [mS, mS, mT, mS, mF, mS]; uniq = [mS, mT, mF];
  }
  uniq.forEach(m => { m.userData = { base: m.color.clone() }; });
  const mesh = new THREE.Mesh(geo, mats);
  mesh.position.set(runX + w / 2, h / 2, -dep / 2);
  const edgeMat = new THREE.LineBasicMaterial({ color: COL.ink });
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(geo), edgeMat);
  edges.raycast = function () {};
  mesh.add(edges);
  gFig.add(mesh);

  const rec = { spec: sp, mesh, mats: uniq, edgeMat, x0: runX, w, h, dep, idx: i };
  blocks.push(rec);
  runX += w + (sp.gapAfter || GAP);

  const shape = sp.t === 'plane' ? '256×256×3' : `${sp.res}×${sp.res}×${sp.ch}`;
  const role = sp.t === 'plane'
    ? (sp.side === 'in' ? 'Noisy image x_t entering the network.'
                        : 'Predicted noise ε̂ leaving the network (same shape as the input).')
    : (sp.part === 'encoder' ? 'Encoder (downsampling) residual block.'
      : sp.part === 'bottleneck' ? 'Bottleneck residual block with self-attention.'
      : 'Decoder (upsampling) residual block, fed by the concatenated encoder features.');
  registerInteractive(mesh, {
    tooltip: shape,
    title: shape,
    body: `${role} Screen height and the receding depth both show the spatial resolution `
        + `(${sp.t === 'plane' ? 256 : sp.res}×${sp.t === 'plane' ? 256 : sp.res}); `
        + `the thickness along the flow direction shows the channel count `
        + `(${sp.t === 'plane' ? 3 : sp.ch}). Resolution halves as channels grow.`
  });
});

const xL = -totalW / 2, xR = totalW / 2;

/* ── inter-block arrows (residual blocks) ────────────────────────────────── */
const ATTN_GAPS = [9, 13, 16];
const ATTN_ADJ  = new Set([9, 10, 13, 14, 16, 17]);
const gapArrows = [], gapCenters = [];
for (let g = 0; g < blocks.length - 1; g++) {
  const a = blocks[g], b = blocks[g + 1];
  const xa = a.x0 + a.w + 0.045, xb = b.x0 - 0.015;
  const isAttn = ATTN_GAPS.includes(g);
  const arr = mkArrow(new THREE.Vector3(xa, 0.09, 0.08),
                      new THREE.Vector3(xb, 0.09, 0.08),
                      isAttn ? COL.attn : COL.rail, { head: 0.12, headR: 0.046 });
  gapArrows.push({ mats: arr.mats, isAttn });
  gapCenters.push((xa + xb) / 2);
}

/* ── skip (Concatenate) connections ──────────────────────────────────────── */
// short steep rise out of the encoder, LONG horizontal rail, short steep drop in.
const SKIPS = [
  { encIdx: 3, decIdx: 23, screenY: 7.20 },
  { encIdx: 5, decIdx: 21, screenY: 5.20 },
  { encIdx: 7, decIdx: 19, screenY: 3.80 },
  { encIdx: 9, decIdx: 17, screenY: 2.50 }
];
SKIPS.forEach(sk => {
  const E = blocks[sk.encIdx], D = blocks[sk.decIdx];
  const dep = E.dep, z = -dep;
  const yL = sk.screenY - SH * dep;
  const p0 = new THREE.Vector3(E.x0 + E.w, E.h, z);
  const p1 = new THREE.Vector3(p0.x + Math.max(0.42, (yL - E.h) * 0.70), yL, z);
  const tip = new THREE.Vector3(D.x0 + D.w, D.h + 0.04, z);
  const p2 = new THREE.Vector3(tip.x + Math.max(0.42, (yL - D.h) * 0.70), yL, z);
  const line = mkLine([p0, p1, p2], COL.skip, { onTop: true, order: 11 });
  const head = mkArrow(p2, tip, COL.skip, { onTop: true, order: 11, head: 0.21, headR: 0.075 });
  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.085, 12, 10),
    new THREE.MeshBasicMaterial({ color: 0xFFB27A }));
  dot.material.depthTest = false; dot.renderOrder = 13; dot.visible = false;
  dot.raycast = function () {};
  gFig.add(dot);
  const pts = [p0, p1, p2, tip], seg = [];
  let tot = 0;
  for (let i = 0; i < pts.length - 1; i++) { const L = pts[i].distanceTo(pts[i + 1]); seg.push(L); tot += L; }
  sk.path = { pts, seg, tot };
  sk.mats = [line.material, ...head.mats];
  sk.dot = dot;
  // 'Concatenate' centred over the long horizontal rail
  sk.mid = new THREE.Vector3((p1.x + p2.x) / 2, yL + 0.45, z);
});
function pathPoint(sk, u) {
  let s = u * sk.path.tot;
  for (let i = 0; i < sk.path.seg.length; i++) {
    if (s <= sk.path.seg[i] || i === sk.path.seg.length - 1) {
      const f = Math.max(0, Math.min(1, s / sk.path.seg[i]));
      return sk.path.pts[i].clone().lerp(sk.path.pts[i + 1], f);
    }
    s -= sk.path.seg[i];
  }
  return sk.path.pts[0].clone();
}

/* ── time embedding rail ─────────────────────────────────────────────────── */
const RAIL_Y = -1.15, RAIL_Z = 0.3;
const tCx = xL - 1.15, tCy = RAIL_Y;
{
  const circ = [];
  for (let i = 0; i <= 48; i++) {
    const a = i / 48 * Math.PI * 2;
    circ.push(new THREE.Vector3(tCx + 0.3 * Math.cos(a), tCy + 0.3 * Math.sin(a), RAIL_Z));
  }
  mkLine(circ, COL.rail, { onTop: true, order: 9 });
}
const railStart = tCx + 0.3, railEnd = xR + 0.35;
mkLine([new THREE.Vector3(railStart, RAIL_Y, RAIL_Z),
        new THREE.Vector3(railEnd, RAIL_Y, RAIL_Z)], COL.rail, { onTop: true, order: 9 });
// long diagonal injection arrows, one per inter-block gap, cone head at the gap
gapCenters.forEach(gx => {
  mkArrow(new THREE.Vector3(gx - 1.05, RAIL_Y + 0.02, RAIL_Z),
          new THREE.Vector3(gx - 0.02, 0.05, RAIL_Z), COL.rail,
          { onTop: true, order: 9, head: 0.22, headR: 0.075 });
});
const railDot = new THREE.Mesh(new THREE.SphereGeometry(0.1, 12, 10),
  new THREE.MeshBasicMaterial({ color: 0x7FB8D6 }));
railDot.material.depthTest = false; railDot.renderOrder = 14;
railDot.raycast = function () {};
gFig.add(railDot);

/* ── dimension leader arrows (screen-space staggered anchors) ────────────── */
const DIMS = [
  { i: 0,  txt: '256×256×3',   sx: -10.50, sy: 8.15 },
  { i: 3,  txt: '256×256×128', sx:  -7.60, sy: 7.72 },
  { i: 5,  txt: '128×128×128', sx:  -6.45, sy: 5.62 },
  { i: 7,  txt: '64×64×256',   sx:  -5.05, sy: 4.22 },
  { i: 9,  txt: '32×32×256',   sx:  -3.30, sy: 2.92 },
  { i: 11, txt: '16×16×512',   sx:  -0.80, sy: 1.72 },
  { i: 13, txt: '8×8×512',     sx:   2.35, sy: 1.58 }
];
DIMS.forEach(dm => {
  const b = blocks[dm.i], dep = b.dep;
  const anchor = new THREE.Vector3(dm.sx - SH * dep, dm.sy - SH * dep, -dep);
  const tgt = new THREE.Vector3(b.x0 + b.w, b.h, -dep);
  const dir = new THREE.Vector3().subVectors(anchor, tgt);
  const dist = Math.max(dir.length(), 1e-4); dir.normalize();
  const L = Math.min(1.45, Math.max(0.5, dist - 0.55));
  const tail = tgt.clone().addScaledVector(dir, L);
  mkArrow(tail, tgt, COL.ink, { onTop: true, order: 12, head: 0.16, headR: 0.052 });
  dm.anchor = anchor;
});

/* ── legend (upper FAR left, clear of the input plane & dimension labels) ── */
const lgW = 4.9, lgH = 2.15, lgX = xL - 3.9, lgY = 6.85, lgZ = 0.35;
mkLine(roundedRect(lgX, lgY, lgW, lgH, 0.17, lgZ), COL.ink, { onTop: true, order: 12 });
mkArrow(new THREE.Vector3(lgX + 3.45, lgY + 1.55, lgZ),
        new THREE.Vector3(lgX + 4.45, lgY + 1.55, lgZ), COL.rail,
        { onTop: true, order: 12, head: 0.18, headR: 0.06 });
mkArrow(new THREE.Vector3(lgX + 3.45, lgY + 0.68, lgZ),
        new THREE.Vector3(lgX + 4.45, lgY + 0.68, lgZ), COL.attn,
        { onTop: true, order: 12, head: 0.18, headR: 0.06 });

/* ── camera ──────────────────────────────────────────────────────────────── */
setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5,
                rollDeg: 0, heightFraction: 0.62 });

