      const low = 0.5 + 0.5 * Math.sin(u * 9 + Math.cos(v * 7) * 1.6);
      r = 210 - 38 * low; g = 176 - 44 * low; b = 156 - 44 * low;
      const les = Math.exp(-Math.pow((rr - 0.05) / 0.19, 2) * 2.2);
      r = r * (1 - 0.6 * les) + 34 * les;
      g = g * (1 - 0.68 * les) + 20 * les;
      b = b * (1 - 0.68 * les) + 16 * les;
    } else { r = g = b = 130; }
    D[i]     = r * (1 - a) + Math.random() * 255 * a;
    D[i + 1] = g * (1 - a) + Math.random() * 255 * a;
    D[i + 2] = b * (1 - a) + Math.random() * 255 * a;
    D[i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(cv);
  tex.magFilter = THREE.NearestFilter; tex.minFilter = THREE.LinearFilter;
  return tex;
}

/* ── block sequence ──────────────────────────────────────────────────────── */
const specs = [];
specs.push({ t: 'plane', side: 'in', sp: 4.0, w: 0.06, ch: 3, res: 256, gapAfter: 0.55 });
const encStages = [
  { res: 256, n: 3, sp: 4.0,   w: 0.35, ch: 128 },
  { res: 128, n: 2, sp: 2.0,   w: 0.35, ch: 128 },
  { res: 64,  n: 2, sp: 1.0,   w: 0.70, ch: 256 },
  { res: 32,  n: 2, sp: 0.5,   w: 0.70, ch: 256 },
  { res: 16,  n: 2, sp: 0.25,  w: 1.40, ch: 512 }
];
encStages.forEach(s => { for (let i = 0; i < s.n; i++)
  specs.push({ t: 'box', part: 'encoder', res: s.res, sp: s.sp, w: s.w, ch: s.ch }); });
for (let i = 0; i < 3; i++)
  specs.push({ t: 'box', part: 'bottleneck', res: 8, sp: 0.125, w: 1.4, ch: 512 });
[...encStages].reverse().forEach(s => { for (let i = 0; i < s.n; i++)
  specs.push({ t: 'box', part: 'decoder', res: s.res, sp: s.sp, w: s.w, ch: s.ch }); });
specs[specs.length - 1].gapAfter = 0.55;
specs.push({ t: 'plane', side: 'out', sp: 4.0, w: 0.06, ch: 3, res: 256 });

const GAP = 0.25;
let totalW = 0;
specs.forEach((s, i) => { totalW += s.w + (i < specs.length - 1 ? (s.gapAfter || GAP) : 0); });

const blocks = [];
let runX = -totalW / 2;
let inputTexHolder = null;
specs.forEach((sp, i) => {
  const h = sp.sp, dep = sp.sp, w = sp.w;
  const geo = new THREE.BoxGeometry(w, h, dep);
  let mats, uniq;
  if (sp.t === 'plane') {
    const tex = noiseTexture(sp.side === 'in' ? 'input' : 'out', 0.25);
    const mTex = new THREE.MeshBasicMaterial({ map: tex });
    const mEdg = new THREE.MeshBasicMaterial({ color: 0xBCBCBC });
    mats = [mTex, mTex, mEdg, mEdg, mEdg, mEdg]; uniq = [mTex, mEdg];
    if (sp.side === 'in') inputTexHolder = { mat: mTex, tex };
  } else {
    const mS = new THREE.MeshBasicMaterial({ color: COL.dark });
    const mT = new THREE.MeshBasicMaterial({ color: COL.top });
    const mF = new THREE.MeshBasicMaterial({ color: COL.front });
    mats = [mS, mS, mT, mS, mF, mS]; uniq = [mS, mT, mF];
  }
  uniq.forEach(m => { m.userData = { base: m.color.clone() }; });
  const mesh = new THREE.Mesh(geo, mats);
  mesh.position.set(runX + w / 2, h / 2, -dep / 2);
  const edgeMat = new THREE.LineBasicMaterial({ color: COL.ink });
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(geo), edgeMat);
  edges.raycast = function () {};
  mesh.add(edges);
  gFig.add(mesh);

  const rec = { spec: sp, mesh, mats: uniq, edgeMat, x0: runX, w, h, dep, idx: i };
  blocks.push(rec);
  runX += w + (sp.gapAfter || GAP);

  const shape = sp.t === 'plane' ? '256×256×3' : `${sp.res}×${sp.res}×${sp.ch}`;
  const role = sp.t === 'plane'
    ? (sp.side === 'in' ? 'Noisy image x_t entering the network.'
                        : 'Predicted noise ε̂ leaving the network (same shape as the input).')
    : (sp.part === 'encoder' ? 'Encoder (downsampling) residual block.'
      : sp.part === 'bottleneck' ? 'Bottleneck residual block with self-attention.'
      : 'Decoder (upsampling) residual block, fed by the concatenated encoder features.');
  registerInteractive(mesh, {
    tooltip: shape,
    title: shape,
    body: `${role} Screen height and the receding depth both show the spatial resolution `
        + `(${sp.t === 'plane' ? 256 : sp.res}×${sp.t === 'plane' ? 256 : sp.res}); `
        + `the thickness along the flow direction shows the channel count `
        + `(${sp.t === 'plane' ? 3 : sp.ch}). Resolution halves as channels grow.`
  });
});

const xL = -totalW / 2, xR = totalW / 2;

/* ── inter-block arrows (residual blocks) ────────────────────────────────── */
const ATTN_GAPS = [9, 13, 16];
const ATTN_ADJ  = new Set([9, 10, 13, 14, 16, 17]);
const gapArrows = [], gapCenters = [];
for (let g = 0; g < blocks.length - 1; g++) {
  const a = blocks[g], b = blocks[g + 1];
  const xa = a.x0 + a.w + 0.045, xb = b.x0 - 0.015;
  const isAttn = ATTN_GAPS.includes(g);
  const arr = mkArrow(new THREE.Vector3(xa, 0.09, 0.08),
                      new THREE.Vector3(xb, 0.09, 0.08),
                      isAttn ? COL.attn : COL.rail, { head: 0.12, headR: 0.046 });
  gapArrows.push({ mats: arr.mats, isAttn });
  gapCenters.push((xa + xb) / 2);
}

/* ── skip (Concatenate) connections ──────────────────────────────────────── */
// short steep rise out of the encoder, LONG horizontal rail, short steep drop in.
const SKIPS = [
  { encIdx: 3, decIdx: 23, screenY: 7.20 },
  { encIdx: 5, decIdx: 21, screenY: 5.20 },
  { encIdx: 7, decIdx: 19, screenY: 3.80 },
  { encIdx: 9, decIdx: 17, screenY: 2.50 }
];
SKIPS.forEach(sk => {
  const E = blocks[sk.encIdx], D = blocks[sk.decIdx];
  const dep = E.dep, z = -dep;
  const yL = sk.screenY - SH * dep;
  const p0 = new THREE.Vector3(E.x0 + E.w, E.h, z);
  const p1 = new THREE.Vector3(p0.x + Math.max(0.42, (yL - E.h) * 0.70), yL, z);
  const tip = new THREE.Vector3(D.x0 + D.w, D.h + 0.04, z);
  const p2 = new THREE.Vector3(tip.x + Math.max(0.42, (yL - D.h) * 0.70), yL, z);
  const line = mkLine([p0, p1, p2], COL.skip, { onTop: true, order: 11 });
  const head = mkArrow(p2, tip, COL.skip, { onTop: true, order: 11, head: 0.21, headR: 0.075 });
  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.085, 12, 10),
    new THREE.MeshBasicMaterial({ color: 0xFFB27A }));
  dot.material.depthTest = false; dot.renderOrder = 13; dot.visible = false;
  dot.raycast = function () {};
  gFig.add(dot);
  const pts = [p0, p1, p2, tip], seg = [];
  let tot = 0;
  for (let i = 0; i < pts.length - 1; i++) { const L = pts[i].distanceTo(pts[i + 1]); seg.push(L); tot += L; }
  sk.path = { pts, seg, tot };
  sk.mats = [line.material, ...head.mats];
  sk.dot = dot;
  // 'Concatenate' centred over the long horizontal rail
  sk.mid = new THREE.Vector3((p1.x + p2.x) / 2, yL + 0.45, z);
});
function pathPoint(sk, u) {
  let s = u * sk.path.tot;
  for (let i = 0; i < sk.path.seg.length; i++) {
    if (s <= sk.path.seg[i] || i === sk.path.seg.length - 1) {
      const f = Math.max(0, Math.min(1, s / sk.path.seg[i]));
      return sk.path.pts[i].clone().lerp(sk.path.pts[i + 1], f);
    }
    s -= sk.path.seg[i];
  }
  return sk.path.pts[0].clone();
}

/* ── time embedding rail ─────────────────────────────────────────────────── */
const RAIL_Y = -1.15, RAIL_Z = 0.3;
const tCx = xL - 1.15, tCy = RAIL_Y;
{
  const circ = [];
  for (let i = 0; i <= 48; i++) {
    const a = i / 48 * Math.PI * 2;
    circ.push(new THREE.Vector3(tCx + 0.3 * Math.cos(a), tCy + 0.3 * Math.sin(a), RAIL_Z));
  }
  mkLine(circ, COL.rail, { onTop: true, order: 9 });
}
const railStart = tCx + 0.3, railEnd = xR + 0.35;
mkLine([new THREE.Vector3(railStart, RAIL_Y, RAIL_Z),
        new THREE.Vector3(railEnd, RAIL_Y, RAIL_Z)], COL.rail, { onTop: true, order: 9 });
// long diagonal injection arrows, one per inter-block gap, cone head at the gap
gapCenters.forEach(gx => {
  mkArrow(new THREE.Vector3(gx - 1.05, RAIL_Y + 0.02, RAIL_Z),
          new THREE.Vector3(gx - 0.02, 0.05, RAIL_Z), COL.rail,
          { onTop: true, order: 9, head: 0.22, headR: 0.075 });
});
const railDot = new THREE.Mesh(new THREE.SphereGeometry(0.1, 12, 10),
  new THREE.MeshBasicMaterial({ color: 0x7FB8D6 }));
railDot.material.depthTest = false; railDot.renderOrder = 14;
railDot.raycast = function () {};
gFig.add(railDot);

/* ── dimension leader arrows (screen-space staggered anchors) ────────────── */
const DIMS = [
  { i: 0,  txt: '256×256×3',   sx: -10.50, sy: 8.15 },
  { i: 3,  txt: '256×256×128', sx:  -7.60, sy: 7.72 },
  { i: 5,  txt: '128×128×128', sx:  -6.45, sy: 5.62 },
  { i: 7,  txt: '64×64×256',   sx:  -5.05, sy: 4.22 },
  { i: 9,  txt: '32×32×256',   sx:  -3.30, sy: 2.92 },
  { i: 11, txt: '16×16×512',   sx:  -0.80, sy: 1.72 },
  { i: 13, txt: '8×8×512',     sx:   2.35, sy: 1.58 }
];
DIMS.forEach(dm => {
  const b = blocks[dm.i], dep = b.dep;
  const anchor = new THREE.Vector3(dm.sx - SH * dep, dm.sy - SH * dep, -dep);
  const tgt = new THREE.Vector3(b.x0 + b.w, b.h, -dep);
  const dir = new THREE.Vector3().subVectors(anchor, tgt);
  const dist = Math.max(dir.length(), 1e-4); dir.normalize();
  const L = Math.min(1.45, Math.max(0.5, dist - 0.55));
  const tail = tgt.clone().addScaledVector(dir, L);
  mkArrow(tail, tgt, COL.ink, { onTop: true, order: 12, head: 0.16, headR: 0.052 });
  dm.anchor = anchor;
});

/* ── legend (upper FAR left, clear of the input plane & dimension labels) ── */
const lgW = 4.9, lgH = 2.15, lgX = xL - 3.9, lgY = 6.85, lgZ = 0.35;
mkLine(roundedRect(lgX, lgY, lgW, lgH, 0.17, lgZ), COL.ink, { onTop: true, order: 12 });
mkArrow(new THREE.Vector3(lgX + 3.45, lgY + 1.55, lgZ),
        new THREE.Vector3(lgX + 4.45, lgY + 1.55, lgZ), COL.rail,
        { onTop: true, order: 12, head: 0.18, headR: 0.06 });
mkArrow(new THREE.Vector3(lgX + 3.45, lgY + 0.68, lgZ),
        new THREE.Vector3(lgX + 4.45, lgY + 0.68, lgZ), COL.attn,
        { onTop: true, order: 12, head: 0.18, headR: 0.06 });

/* ── camera ──────────────────────────────────────────────────────────────── */
setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5,
                rollDeg: 0, heightFraction: 0.62 });

/* ── labels (font size scaled to the on-screen size of the figure) ───────── */
const _cv = document.getElementById('c');
const PPU = Math.max(6, (_cv.clientHeight || 700) / 2 * (camera.zoom || 0.2) / 3);
const FS = k => Math.max(8.5, Math.min(16, PPU * k)).toFixed(1) + 'px';

const dimStyle = (t) => `<span style="display:inline-block;transform:rotate(-21deg);`
  + `font-family:Georgia,'Times New Roman',serif;font-style:italic;color:#333">${t}</span>`;
DIMS.forEach(dm => addLabel(dimStyle(dm.txt), dm.anchor, { fontSize: FS(0.50) }));

SKIPS.forEach(sk => addLabel('Concatenate', sk.mid,
  { color: '#A0522D', fontSize: FS(0.60) }));

addLabel('<i>t</i>', new THREE.Vector3(tCx, tCy, RAIL_Z), { fontSize: FS(0.52) });
const tLbl = addLabel('t = 250', new THREE.Vector3(tCx, tCy - 0.66, RAIL_Z),
  { fontSize: FS(0.46), color: '#3F5E6E' });
addLabel('time embedding', new THREE.Vector3(xL + 2.0, RAIL_Y - 0.55, RAIL_Z),
  { color: '#2F5060', fontSize: FS(0.56) });

addLabel('Res. block', new THREE.Vector3(lgX + 1.75, lgY + 1.55, lgZ),
  { fontSize: FS(0.47), color: '#111' });
addLabel('Res. block +<br>self-attention', new THREE.Vector3(lgX + 1.75, lgY + 0.70, lgZ),
  { fontSize: FS(0.47), color: '#6A9FBF' });

/* ── state & interactions ────────────────────────────────────────────────── */
const RANGES = {
  'full':        [0, blocks.length - 1],
  'encoder-256': [0, 4],
  'encoder-down':[3, 12],
  'bottleneck':  [11, 15],
  'decoder':     [14, blocks.length - 1]
};
const state = { playing: true, cursor: 0, range: RANGES.full, mode: 'all',
                tCur: 250, tTarget: 250, pass: 'full' };

const elPlay = document.getElementById('btnPlay');
const elRestart = document.getElementById('btnRestart');
const elWhere = document.getElementById('passWhere');
const elT = document.getElementById('sldT');
const elTv = document.getElementById('tVal');
const elNarr = document.getElementById('narr');
const modeBtns = [document.getElementById('btMode0'),
                  document.getElementById('btMode1'),
                  document.getElementById('btMode2')];
const MODES = ['all', 'res', 'attn'];

function setPass(name) {
  state.pass = name;
  if (name === 'idle') { state.playing = false; }
  else {
    state.range = RANGES[name] || RANGES.full;
    state.cursor = state.range[0] - 0.8;
    state.playing = true;
  }
  elPlay.textContent = state.playing ? '⏸ Pause pass' : '▶ Play pass';
  elPlay.classList.toggle('active', state.playing);
}
function setMode(m) {
  state.mode = m;
  modeBtns.forEach((b, i) => b.classList.toggle('active', MODES[i] === m));
}
elPlay.addEventListener('click', () => {
  state.playing = !state.playing;
  if (state.playing && state.pass === 'idle') { setPass('full'); return; }
  elPlay.textContent = state.playing ? '⏸ Pause pass' : '▶ Play pass';
  elPlay.classList.toggle('active', state.playing);
});
elRestart.addEventListener('click', () => { state.cursor = state.range[0] - 0.8; });
modeBtns.forEach((b, i) => b.addEventListener('click', () => setMode(MODES[i])));
elT.addEventListener('input', () => { state.tTarget = +elT.value; });

/* demo steps */
const STEPS = [
  { title: 'Noisy input',
    narration: 'A 256×256×3 noisy image enters at the left. The first residual blocks lift it to 256×256×128 — tall slabs, still full spatial resolution.',
    s: { pass: 'encoder-256', t: 250, mode: 'all' } },
  { title: 'Downsampling',
    narration: 'Each stage halves the spatial size and (twice) doubles the channels: 128×128×128, 64×64×256, 32×32×256, 16×16×512. The boxes get shorter and longer.',
    s: { pass: 'encoder-down', t: 250, mode: 'all' } },
  { title: 'Self-attention stages',
    narration: 'Light blue arrows mark residual blocks with self-attention. They appear only at 16×16 and in the 8×8×512 bottleneck, where global mixing is cheap.',
    s: { pass: 'bottleneck', t: 250, mode: 'attn' } },
  { title: 'Decoder and skip concatenation',
    narration: 'On the way back up, each decoder stage receives the encoder feature map of matching resolution along the salmon Concatenate rails, restoring the fine detail lost by downsampling.',
    s: { pass: 'decoder', t: 250, mode: 'all' } },
  { title: 'Timestep conditioning',
    narration: 'Sweep t: the embedding of the circled t travels the bottom rail and is injected into every residual block, telling the network how much noise to expect and predict.',
    s: { pass: 'idle', t: 900, mode: 'all' } }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  setPass(st.s.pass);
  state.tTarget = st.s.t; elT.value = st.s.t;
  setMode(st.s.mode);
  elNarr.innerHTML = `<b>${stepIdx + 1}/${STEPS.length} · ${st.title}</b><br>${st.narration}`;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);

/* ── per-frame update ────────────────────────────────────────────────────── */
let lastQ = -1, railPhase = 0, lastTime = performance.now();
function refreshT() {
  const v = Math.round(state.tCur);
  elTv.textContent = v;
  tLbl.div.innerHTML = 't = ' + v;
  const q = Math.round(state.tCur / 20);
  if (q !== lastQ && inputTexHolder) {
    lastQ = q;
    const old = inputTexHolder.tex;
    const tex = noiseTexture('input', Math.pow(state.tCur / 1000, 0.7));
    inputTexHolder.tex = tex;
    inputTexHolder.mat.map = tex;
    inputTexHolder.mat.needsUpdate = true;
    old.dispose();
  }
}
refreshT();

function applyVisuals() {
  const active = state.playing;
  blocks.forEach((b, i) => {
    let dim = false;
    if (state.mode === 'res') dim = ATTN_ADJ.has(i);
    else if (state.mode === 'attn') dim = !ATTN_ADJ.has(i);
    const op = dim ? 0.18 : 1;
    const pulse = active ? Math.max(0, 1 - Math.abs(state.cursor - i) / 1.3) : 0;
    b.mats.forEach(m => {
      m.opacity = op; m.transparent = op < 1;
      m.color.copy(m.userData.base);
      if (pulse > 0) m.color.lerp(HL, 0.72 * pulse);
    });
    b.edgeMat.opacity = op; b.edgeMat.transparent = op < 1;
  });
  gapArrows.forEach(ga => {
    let dim = false;
    if (state.mode === 'res') dim = ga.isAttn;
    else if (state.mode === 'attn') dim = !ga.isAttn;
    const op = dim ? 0.18 : 1;
    ga.mats.forEach(m => { m.opacity = op; m.transparent = op < 1; });
  });
  SKIPS.forEach(sk => {
    const u = (state.cursor - (sk.decIdx - 2.2)) / 2.2;
    const on = state.playing && u >= 0 && u <= 1.04;
    sk.dot.visible = on;
    if (on) sk.dot.position.copy(pathPoint(sk, Math.min(1, u)));
    sk.mats.forEach(m => { m.color.copy(on ? SKIP_H : SKIP_B); });
  });
}

function whereText() {
  if (!state.playing) return 'pass paused · t held';
  const i = Math.round(Math.max(0, Math.min(blocks.length - 1, state.cursor)));
  const sp = blocks[i].spec;
  if (sp.t === 'plane') return sp.side === 'in' ? 'input · 256×256×3' : 'output · predicted noise';
  return `${sp.part} · ${sp.res}×${sp.res}×${sp.ch}`;
}

function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - lastTime) / 1000);
  lastTime = now;

  if (Math.abs(state.tCur - state.tTarget) > 0.4) {
    state.tCur += (state.tTarget - state.tCur) * Math.min(1, dt * 6);
    refreshT();
  } else if (state.tCur !== state.tTarget) { state.tCur = state.tTarget; refreshT(); }

  if (state.playing) {
    state.cursor += dt * 3.0;
    if (state.cursor > state.range[1] + 1.4) state.cursor = state.range[0] - 0.8;
  }
  railPhase = (railPhase + dt * (0.12 + state.tCur / 2600)) % 1;
  railDot.position.set(railStart + (railEnd - railStart) * railPhase, RAIL_Y, RAIL_Z);
  railDot.material.color.setHSL(0.55, 0.45, 0.35 + 0.35 * (1 - state.tCur / 1000));

  applyVisuals();
  elWhere.textContent = whereText();
}
tick();

document.getElementById('btnReset').style.display = '';
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

