// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ────────────────────────────────────────────────────────────
// noisy input plane      → BoxGeometry(0.06, 4, 4)  CanvasTexture: dermoscopy
//                          photo blended with gaussian noise by ᾱ(t)  (on ±X faces)
// noisy output plane     → BoxGeometry(0.06, 4, 4)  CanvasTexture pure grey noise
// feature-map blocks     → BoxGeometry(channelThickness, spatial, spatial)
//                          +X/-X side faces dark brown #8A3A20 (large sheared face),
//                          +Z front + top faces light salmon #E08A62 / #EFA57E
// block outlines         → LineSegments(EdgesGeometry) black, raycast disabled
// res-block arrows       → Line + ConeGeometry head, #3F5E6E (between blocks)
// self-attn arrows       → Line + ConeGeometry head, #9CC4DA (exactly 3 gaps)
// skip connections       → rise up-right from enc top-right → LONG horizontal rail
//                          → descend down-RIGHT into decoder top-left + cone head
// skip travelling dot    → SphereGeometry(0.085) salmon
// time rail              → Line y=-1.15 + LineLoop circle (radius .3) for 't'
// time injection arrows  → Line + cone, #3F5E6E, ONE PER GAP, length ∝ local block width
// legend                 → small rounded-rect LineLoop (upper far left) + 2 arrows + HTML
// dimension leaders      → short Line + cone, black, pointing down-left at block corner
// all text               → addLabel HTML (italic serif for dimensions), size ∝ zoom
─────────────────────────────────────────────────────────────────────────────*/

const COL = {
  dark: 0x8A3A20, front: 0xE08A62, top: 0xEFA57E,
  skip: 0xC86B45, rail: 0x3F5E6E, attn: 0x9CC4DA, ink: 0x111111
};
const HL      = new THREE.Color(0xFFD9A0);
const SKIP_B  = new THREE.Color(COL.skip);
const SKIP_H  = new THREE.Color(0xFF9B58);
const SH      = 0.35355;               // cabinet-oblique screen shift per unit depth

const gFig = new THREE.Group();  scene.add(gFig);

/* ── helpers ─────────────────────────────────────────────────────────────── */
function mkLine(points, color, opts = {}) {
  const l = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(points),
    new THREE.LineBasicMaterial({ color })
  );
  l.raycast = function () {};
  if (opts.onTop) { l.material.depthTest = false; l.renderOrder = opts.order || 10; }
  gFig.add(l);
  return l;
}
function mkArrow(from, to, color, opts = {}) {
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = Math.max(dir.length(), 1e-5); dir.normalize();
  const hl = Math.min(opts.head || 0.14, len * 0.8), hr = opts.headR || 0.052;
  const line = mkLine([from, to.clone().addScaledVector(dir, -hl * 0.75)], color, opts);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(hr, hl, 14),
    new THREE.MeshBasicMaterial({ color }));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  cone.position.copy(to).addScaledVector(dir, -hl / 2);
  if (opts.onTop) { cone.material.depthTest = false; cone.renderOrder = opts.order || 10; }
  cone.raycast = function () {};
  gFig.add(cone);
  return { mats: [line.material, cone.material] };
}
function roundedRect(x, y, w, h, r, z) {
  const pts = [], S = 5;
  const cs = [[x + w - r, y + r, -Math.PI / 2], [x + w - r, y + h - r, 0],
              [x + r, y + h - r, Math.PI / 2], [x + r, y + r, Math.PI]];
  cs.forEach(([cx, cy, a0]) => {
    for (let i = 0; i <= S; i++) {
      const a = a0 + (Math.PI / 2) * (i / S);
      pts.push(new THREE.Vector3(cx + r * Math.cos(a), cy + r * Math.sin(a), z));
    }
  });
  pts.push(pts[0].clone());
  return pts;
}
function gauss() {
  let u = 0, v = 0;
  while (u === 0) u = Math.random();
  while (v === 0) v = Math.random();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}

/* ── image textures: a real-looking dermoscopy photo + diffusion noise ────── */
const TEXN = 168;
function makeSkinData(N) {
  const cv = document.createElement('canvas'); cv.width = cv.height = N;
  const ctx = cv.getContext('2d');
  const g = ctx.createRadialGradient(N * 0.5, N * 0.42, N * 0.08, N * 0.5, N * 0.5, N * 0.8);
  g.addColorStop(0, '#F4D2B2'); g.addColorStop(0.55, '#DCAC88'); g.addColorStop(1, '#B27A58');
  ctx.fillStyle = g; ctx.fillRect(0, 0, N, N);
  // skin mottling
  for (let i = 0; i < 300; i++) {
    const x = Math.random() * N, y = Math.random() * N, r = N * (0.012 + Math.random() * 0.055);
    ctx.globalAlpha = 0.06 + Math.random() * 0.10;
    ctx.fillStyle = Math.random() < 0.5 ? '#A26A46' : '#F8E0C8';
    ctx.beginPath();
    ctx.ellipse(x, y, r, r * (0.55 + Math.random() * 0.9), Math.random() * 3.14, 0, 6.2832);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  // irregular pigmented lesion (3 nested lobes)
  const cx = N * 0.45, cy = N * 0.54;
  const cols = ['#7A4A32', '#4B2A1B', '#2A150E'];
  const scl = [1.0, 0.74, 0.44];
  for (let L = 0; L < 3; L++) {
    ctx.globalAlpha = L === 0 ? 0.88 : 0.92;
    ctx.fillStyle = cols[L];
    ctx.beginPath();
    for (let a = 0; a <= 72; a++) {
      const th = a / 72 * Math.PI * 2;
      const r = N * 0.235 * scl[L] *
        (1 + 0.26 * Math.sin(3 * th + L * 1.1) + 0.14 * Math.sin(7 * th + 2 * L) + 0.07 * Math.sin(11 * th));
      const x = cx + r * Math.cos(th), y = cy + r * Math.sin(th) * 0.93;
      if (a === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.closePath(); ctx.fill();
  }
  ctx.globalAlpha = 1;
  // satellite pigment dots
  for (let i = 0; i < 26; i++) {
    const a = Math.random() * 6.2832, rr = N * (0.20 + Math.random() * 0.16);
    ctx.globalAlpha = 0.45 + Math.random() * 0.4;
    ctx.fillStyle = '#3C2117';
    ctx.beginPath();
    ctx.ellipse(cx + rr * Math.cos(a), cy + rr * Math.sin(a) * 0.9,
      N * 0.011 * (0.6 + Math.random()), N * 0.011 * (0.6 + Math.random()), 0, 0, 6.2832);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  // hairs
  ctx.strokeStyle = '#3E2A1E'; ctx.lineWidth = Math.max(1, N * 0.007);
  for (let i = 0; i < 8; i++) {
    ctx.globalAlpha = 0.45 + Math.random() * 0.3;
    const x = Math.random() * N, y = Math.random() * N * 0.5;
    ctx.beginPath(); ctx.moveTo(x, y);
    ctx.bezierCurveTo(x + N * 0.25 * (Math.random() - 0.5), y + N * 0.22,
                      x + N * 0.35 * (Math.random() - 0.5), y + N * 0.42,
                      x + N * 0.30 * (Math.random() - 0.5), y + N * 0.62);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
  // dermoscopy vignette
  const v = ctx.createRadialGradient(N / 2, N / 2, N * 0.33, N / 2, N / 2, N * 0.58);
  v.addColorStop(0, 'rgba(0,0,0,0)'); v.addColorStop(1, 'rgba(18,9,4,0.6)');
  ctx.fillStyle = v; ctx.fillRect(0, 0, N, N);
  return ctx.getImageData(0, 0, N, N);
}
const SKIN = makeSkinData(TEXN);

function diffusedTexture(tNorm) {
  // cosine schedule: x_t = sqrt(abar)*x0 + sqrt(1-abar)*eps
  const abar = Math.pow(Math.cos(Math.min(1, Math.max(0, tNorm)) * Math.PI / 2), 2);
  const sa = Math.sqrt(abar), sb = Math.sqrt(1 - abar);
  const N = TEXN, cv = document.createElement('canvas'); cv.width = cv.height = N;
  const ctx = cv.getContext('2d');
  const out = ctx.createImageData(N, N), S = SKIN.data, D = out.data;
  for (let i = 0; i < D.length; i += 4) {
    for (let k = 0; k < 3; k++) {
      const n = 128 + 80 * gauss();
      let v = sa * S[i + k] + sb * n;
      D[i + k] = v < 0 ? 0 : v > 255 ? 255 : v;
    }
    D[i + 3] = 255;
  }
  ctx.putImageData(out, 0, 0);
  const tex = new THREE.CanvasTexture(cv);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.magFilter = THREE.LinearFilter; tex.minFilter = THREE.LinearFilter;
  return tex;
}
function greyNoiseTexture() {
  const N = TEXN, cv = document.createElement('canvas'); cv.width = cv.height = N;
  const ctx = cv.getContext('2d'), out = ctx.createImageData(N, N), D = out.data;
  for (let i = 0; i < D.length; i += 4) {
    const v = Math.max(0, Math.min(255, 132 + 74 * gauss()));
    D[i] = D[i + 1] = D[i + 2] = v; D[i + 3] = 255;
  }
  ctx.putImageData(out, 0, 0);
  const tex = new THREE.CanvasTexture(cv);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.magFilter = THREE.NearestFilter; tex.minFilter = THREE.LinearFilter;
  return tex;
}

/* ── block sequence ──────────────────────────────────────────────────────── */
const specs = [];
specs.push({ t: 'plane', side: 'in', sp: 4.0, w: 0.06, ch: 3, res: 256, gapAfter: 0.55 });
const encStages = [
  { res: 256, n: 3, sp: 4.0,   w: 0.35, ch: 128 },
  { res: 128, n: 2, sp: 2.0,   w: 0.35, ch: 128 },
  { res: 64,  n: 2, sp: 1.0,   w: 0.70, ch: 256 },
  { res: 32,  n: 2, sp: 0.5,   w: 0.70, ch: 256 },
  { res: 16,  n: 2, sp: 0.25,  w: 1.40, ch: 512 }
];
encStages.forEach(s => { for (let i = 0; i < s.n; i++)
  specs.push({ t: 'box', part: 'encoder', res: s.res, sp: s.sp, w: s.w, ch: s.ch }); });
for (let i = 0; i < 3; i++)
  specs.push({ t: 'box', part: 'bottleneck', res: 8, sp: 0.125, w: 1.4, ch: 512 });
[...encStages].reverse().forEach(s => { for (let i = 0; i < s.n; i++)
  specs.push({ t: 'box', part: 'decoder', res: s.res, sp: s.sp, w: s.w, ch: s.ch }); });
specs[specs.length - 1].gapAfter = 0.55;
specs.push({ t: 'plane', side: 'out', sp: 4.0, w: 0.06, ch: 3, res: 256 });

const GAP = 0.25;
let totalW = 0;
specs.forEach((s, i) => { totalW += s.w + (i < specs.length - 1 ? (s.gapAfter || GAP) : 0); });

const blocks = [];
let runX = -totalW / 2;
let inputTexHolder = null;
specs.forEach((sp, i) => {
  const h = sp.sp, dep = sp.sp, w = sp.w;
  const geo = new THREE.BoxGeometry(w, h, dep);
  let mats, uniq;
  if (sp.t === 'plane') {
    const tex = sp.side === 'in' ? diffusedTexture(0.25) : greyNoiseTexture();
    const mTex = new THREE.MeshBasicMaterial({ map: tex });
    const mEdg = new THREE.MeshBasicMaterial({ color: 0xB0B0B0 });
    mats = [mTex, mTex, mEdg, mEdg, mEdg, mEdg]; uniq = [mTex, mEdg];
    if (sp.side === 'in') inputTexHolder = { mat: mTex, tex };
  } else {
    const mS = new THREE.MeshBasicMaterial({ color: COL.dark });
    const mT = new THREE.MeshBasicMaterial({ color: COL.top });
    const mF = new THREE.MeshBasicMaterial({ color: COL.front });
    mats = [mS, mS, mT, mS, mF, mS]; uniq = [mS, mT, mF];
  }
  uniq.forEach(m => { m.userData = { base: m.color.clone() }; });
  const mesh = new THREE.Mesh(geo, mats);
  mesh.position.set(runX + w / 2, h / 2, -dep / 2);
  const edgeMat = new THREE.LineBasicMaterial({ color: COL.ink });
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(geo), edgeMat);
  edges.raycast = function () {};
  mesh.add(edges);
  gFig.add(mesh);

  const rec = { spec: sp, mesh, mats: uniq, edgeMat, x0: runX, w, h, dep, idx: i };
  blocks.push(rec);
  runX += w + (sp.gapAfter || GAP);

  const shape = sp.t === 'plane' ? '256×256×3' : `${sp.res}×${sp.res}×${sp.ch}`;
  const role = sp.t === 'plane'
    ? (sp.side === 'in' ? 'Noisy image x_t entering the network.'
                        : 'Predicted noise ε̂ leaving the network (same shape as the input).')
    : (sp.part === 'encoder' ? 'Encoder (downsampling) residual block.'
      : sp.part === 'bottleneck' ? 'Bottleneck residual block with self-attention.'
      : 'Decoder (upsampling) residual block, fed by the concatenated encoder features.');
  registerInteractive(mesh, {
    tooltip: shape,
    title: shape,
    body: `${role} Screen height and the receding depth both show the spatial resolution `
        + `(${sp.t === 'plane' ? 256 : sp.res}×${sp.t === 'plane' ? 256 : sp.res}); `
        + `the thickness along the flow direction shows the channel count `
        + `(${sp.t === 'plane' ? 3 : sp.ch}). Resolution halves as channels grow.`
  });
});

const xL = -totalW / 2, xR = totalW / 2;

/* ── inter-block arrows (residual blocks) ────────────────────────────────── */
const ATTN_GAPS = [9, 13, 16];
const ATTN_ADJ  = new Set([9, 10, 13, 14, 16, 17]);
const gapArrows = [], gapCenters = [];
for (let g = 0; g < blocks.length - 1; g++) {
  const a = blocks[g], b = blocks[g + 1];
  const xa = a.x0 + a.w + 0.045, xb = b.x0 - 0.015;
  const isAttn = ATTN_GAPS.includes(g);
  const arr = mkArrow(new THREE.Vector3(xa, 0.09, 0.08),
                      new THREE.Vector3(xb, 0.09, 0.08),
                      isAttn ? COL.attn : COL.rail, { head: 0.12, headR: 0.046 });
  gapArrows.push({ mats: arr.mats, isAttn });
  gapCenters.push({ x: (xa + xb) / 2, wMean: (a.w + b.w) / 2 });
}

/* ── skip (Concatenate) connections ──────────────────────────────────────── */
// rise up-right out of the encoder → LONG horizontal rail → descend down-RIGHT
// into the decoder block's top-left corner (as printed).
const SKIPS = [
  { encIdx: 3, decIdx: 23, screenY: 7.30 },
  { encIdx: 5, decIdx: 21, screenY: 5.35 },
  { encIdx: 7, decIdx: 19, screenY: 3.95 },
  { encIdx: 9, decIdx: 17, screenY: 2.65 }
];
SKIPS.forEach(sk => {
  const E = blocks[sk.encIdx], D = blocks[sk.decIdx];
  const dep = E.dep, z = -dep;
  const yL = sk.screenY - SH * dep;
  const p0 = new THREE.Vector3(E.x0 + E.w, E.h, z);
  const p1 = new THREE.Vector3(p0.x + Math.max(0.45, (yL - E.h) * 0.70), yL, z);
  const tip = new THREE.Vector3(D.x0, D.h + 0.04, z);
  const p2 = new THREE.Vector3(tip.x - Math.max(0.45, (yL - D.h) * 0.70), yL, z);
  const line = mkLine([p0, p1, p2], COL.skip, { onTop: true, order: 11 });
  const head = mkArrow(p2, tip, COL.skip, { onTop: true, order: 11, head: 0.22, headR: 0.078 });
  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.085, 12, 10),
    new THREE.MeshBasicMaterial({ color: 0xFFB27A }));
  dot.material.depthTest = false; dot.renderOrder = 13; dot.visible = false;
  dot.raycast = function () {};
  gFig.add(dot);
  const pts = [p0, p1, p2, tip], seg = [];
  let tot = 0;
  for (let i = 0; i < pts.length - 1; i++) { const L = pts[i].distanceTo(pts[i + 1]); seg.push(L); tot += L; }
  sk.path = { pts, seg, tot };
  sk.mats = [line.material, ...head.mats];
  sk.dot = dot;
  sk.mid = new THREE.Vector3((p1.x + p2.x) / 2, yL + 0.46, z);
});
function pathPoint(sk, u) {
  let s = u * sk.path.tot;
  for (let i = 0; i < sk.path.seg.length; i++) {
    if (s <= sk.path.seg[i] || i === sk.path.seg.length - 1) {
      const f = Math.max(0, Math.min(1, s / sk.path.seg[i]));
      return sk.path.pts[i].clone().lerp(sk.path.pts[i + 1], f);
    }
    s -= sk.path.seg[i];
  }
  return sk.path.pts[0].clone();
}

/* ── time embedding rail ─────────────────────────────────────────────────── */
const RAIL_Y = -1.15, RAIL_Z = 0.3;
const tCx = xL - 1.05, tCy = RAIL_Y;
{
  const circ = [];
  for (let i = 0; i <= 48; i++) {
    const a = i / 48 * Math.PI * 2;
    circ.push(new THREE.Vector3(tCx + 0.3 * Math.cos(a), tCy + 0.3 * Math.sin(a), RAIL_Z));
  }
  mkLine(circ, COL.rail, { onTop: true, order: 9 });
}
const railStart = tCx + 0.3, railEnd = xR + 0.35;
mkLine([new THREE.Vector3(railStart, RAIL_Y, RAIL_Z),
        new THREE.Vector3(railEnd, RAIL_Y, RAIL_Z)], COL.rail, { onTop: true, order: 9 });
// injection arrows: one per gap, length varies with the local block spacing
gapCenters.forEach(gc => {
  const off = Math.min(1.35, Math.max(0.45, 0.30 + 1.15 * gc.wMean));
  mkArrow(new THREE.Vector3(gc.x - off, RAIL_Y + 0.02, RAIL_Z),
          new THREE.Vector3(gc.x - 0.02, 0.05, RAIL_Z), COL.rail,
          { onTop: true, order: 9, head: 0.20, headR: 0.068 });
});
const railDot = new THREE.Mesh(new THREE.SphereGeometry(0.1, 12, 10),
  new THREE.MeshBasicMaterial({ color: 0x7FB8D6 }));
railDot.material.depthTest = false; railDot.renderOrder = 14;
railDot.raycast = function () {};
gFig.add(railDot);

/* ── dimension leader arrows (screen-space staggered anchors) ────────────── */
const DIMS = [
  { i: 0,  txt: '256×256×3',   sx: -10.55, sy: 8.60 },
  { i: 3,  txt: '256×256×128', sx:  -7.95, sy: 8.10 },
  { i: 5,  txt: '128×128×128', sx:  -6.60, sy: 6.00 },
  { i: 7,  txt: '64×64×256',   sx:  -5.10, sy: 4.55 },
  { i: 9,  txt: '32×32×256',   sx:  -3.35, sy: 3.15 },
  { i: 11, txt: '16×16×512',   sx:  -0.90, sy: 1.90 },
  { i: 13, txt: '8×8×512',     sx:   2.30, sy: 1.75 }
];
DIMS.forEach(dm => {
  const b = blocks[dm.i], dep = b.dep;
  const anchor = new THREE.Vector3(dm.sx - SH * dep, dm.sy - SH * dep, -dep);
  const tgt = new THREE.Vector3(b.x0 + b.w, b.h, -dep);
  const dir = new THREE.Vector3().subVectors(anchor, tgt);
  const dist = Math.max(dir.length(), 1e-4); dir.normalize();
  const L = Math.min(1.45, Math.max(0.5, dist - 0.60));
  const tail = tgt.clone().addScaledVector(dir, L);
  mkArrow(tail, tgt, COL.ink, { onTop: true, order: 12, head: 0.16, headR: 0.052 });
  dm.anchor = anchor;
});

/* ── legend (compact, upper far left, clear of the first dimension label) ── */
const lgW = 3.55, lgH = 1.90, lgX = xL - 2.35, lgY = 7.45, lgZ = 0.4;
mkLine(roundedRect(lgX, lgY, lgW, lgH, 0.16, lgZ), COL.ink, { onTop: true, order: 12 });
mkArrow(new THREE.Vector3(lgX + 2.42, lgY + 1.36, lgZ),
        new THREE.Vector3(lgX + 3.28, lgY + 1.36, lgZ), COL.rail,
        { onTop: true, order: 12, head: 0.17, headR: 0.055 });
mkArrow(new THREE.Vector3(lgX + 2.42, lgY + 0.58, lgZ),
        new THREE.Vector3(lgX + 3.28, lgY + 0.58, lgZ), COL.attn,
        { onTop: true, order: 12, head: 0.17, headR: 0.055 });

/* ── camera (large framing: the figure should fill the canvas) ───────────── */
setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5,
                rollDeg: 0, heightFraction: 0.95 });

/* ── labels (font size tracks the on-screen size of the figure) ──────────── */
const _cv = document.getElementById('c');
function PPU() { return Math.max(6, (_cv.clientHeight || 700) / 2 * (camera.zoom || 0.2) / 3); }
